http {
    gzip on;
    gzip_vary on;
    gzip_types text/html text/css application/javascript application/json image/svg+xml;
    server {
        listen 80;
        server_name www.example.com;
        root /var/www/site;
    }
}

http {
    gzip on;
    gzip_min_length 1024;
    gzip_comp_level 6;
    gzip_buffers 4 16k;
    gzip_types text/html text/css application/javascript;
}

server {
    listen 80;
    server_name api.example.com;
    gzip on;
    gzip_vary on;
    gzip_min_length 512;
    gzip_types application/json;
    location / {
        proxy_pass http://127.0.0.1:8080;
        proxy_set_header Host $host;
    }
}

http {
    gzip on;
    gzip_disable "msie6";
    gzip_types text/html text/css application/javascript application/json;
    gzip_vary on;
}

http {
    gzip on;
    gzip_proxied no-cache no-store private;
    gzip_vary on;
    gzip_types text/html text/css application/json;
}

server {
    listen 80;
    server_name www.marketing-site.example;
    root /var/www/marketing-site;
    gzip_static on;
    location / {
        try_files $uri $uri/ =404;
    }
}

server {
    listen 80;
    server_name kb.example.com;
    root /var/www/kb;
    gzip on;
    gzip_comp_level 9;
    gzip_types text/html;
    gzip_min_length 256;
}

http {
    gzip on;
    gzip_comp_level 1;
    gzip_min_length 4096;
    gzip_types text/html text/css;
    gzip_vary on;
}

server {
    listen 80;
    server_name www.corp.example;
    root /var/www/corp;
    gzip on;
    gzip_types text/html text/css application/javascript;
    gzip_vary on;
}

server {
    listen 80;
    server_name legacy-app.example.com;
    root /var/www/legacy-app;
    gzip on;
    gzip_comp_level 5;
    gzip_types text/html text/css application/javascript;
}

location /assets/ {
    root /var/www/storefront;
    gzip on;
    gzip_min_length 512;
    gzip_types text/css application/javascript image/svg+xml;
    gzip_vary on;
    try_files $uri =404;
}

http {
    gzip on;
    gzip_http_version 1.1;
    gzip_vary on;
    gzip_types text/html text/css application/javascript application/json;
}

location / {
    proxy_pass http://127.0.0.1:8100;
    gzip on;
    gzip_buffers 4 32k;
    gzip_types application/json text/html;
    gzip_vary on;
    proxy_set_header Host $host;
}

server {
    listen 443 ssl;
    server_name news.example.com;
    ssl_certificate /etc/nginx/tls/news.pem;
    ssl_certificate_key /etc/nginx/tls/news.key;
    root /var/www/news;
    gzip on;
    gzip_vary on;
    gzip_min_length 1000;
    gzip_types text/html text/css application/javascript application/json;
}

location /downloads/ {
    root /var/www;
    gzip off;
    try_files $uri =404;
}

server {
    listen 80;
    server_name blog.example.com;
    root /var/www/blog;
    gzip on;
    gzip_types text/html text/xml application/rss+xml application/atom+xml;
    gzip_vary on;
}

server {
    listen 80;
    server_name ds.example.com;
    root /var/www/design-system;
    gzip on;
    gzip_types image/svg+xml application/manifest+json text/css;
    gzip_min_length 256;
}

location /reports/ {
    root /var/www/analytics;
    gzip on;
    gzip_types text/csv text/plain text/tab-separated-values;
    gzip_min_length 2048;
    try_files $uri =404;
}

location /dist/ {
    root /var/www/devportal;
    gzip on;
    gzip_comp_level 6;
    gzip_types application/javascript application/json;
    gzip_min_length 128;
    try_files $uri =404;
}

http {
    gzip on;
    gzip_comp_level 6;
    gzip_min_length 256;
    gzip_vary on;
    gzip_proxied any;
    gzip_disable "msie6";
    gzip_types text/html text/css application/javascript application/json image/svg+xml;
    server {
        listen 80;
        server_name www.example.com;
        root /var/www/site;
    }
}
